import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';

const Chat = ({ currentUser, users }) => {
  const [socket, setSocket] = useState(null);
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [typing, setTyping] = useState(false);
  const [userTyping, setUserTyping] = useState(null);
  const [unreadCount, setUnreadCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState('connecting');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [permissionGranted, setPermissionGranted] = useState(false);
  const messagesEndRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const audioRef = useRef(null);
  const notificationSoundRef = useRef(null);

  const currentUsername = currentUser?.name || currentUser?.email?.split('@')[0] || 'Guest';

  // Request notification permission on mount
  useEffect(() => {
    if ('Notification' in window) {
      if (Notification.permission === 'granted') {
        setPermissionGranted(true);
        console.log('Notification permission already granted');
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission().then(permission => {
          if (permission === 'granted') {
            setPermissionGranted(true);
            console.log('Notification permission granted');
          }
        });
      }
    }

    // Create audio elements
    audioRef.current = new Audio('https://www.soundjay.com/misc/sounds/bell-ringing-05.mp3');
    audioRef.current.volume = 0.5;
    audioRef.current.load();

    notificationSoundRef.current = new Audio('https://www.soundjay.com/misc/sounds/notification-01.mp3');
    notificationSoundRef.current.volume = 0.6;
    notificationSoundRef.current.load();

    // Welcome console log
    console.log('Chat service initialized for:', currentUsername);
    console.log('Notification permission:', Notification.permission);
  }, []);

  // Socket connection - runs ALWAYS, even when chat is closed
  useEffect(() => {
    if (!currentUsername) return;

    console.log('Connecting to chat server as:', currentUsername);

    const newSocket = io('http://localhost:3000', {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 1000
    });

    newSocket.on('connect', () => {
      console.log('✅ Chat connected!');
      setConnectionStatus('connected');
      newSocket.emit('user-join', { 
        name: currentUsername, 
        email: currentUser?.email,
        room: 'general' 
      });
    });

    newSocket.on('connect_error', (error) => {
      console.error('Connection error:', error);
      setConnectionStatus('error');
    });

    newSocket.on('message-history', (history) => {
      console.log('Loaded message history:', history.length);
      setMessages(history);
    });

    // ========== KEY: Handle new messages with guaranteed notifications ==========
    newSocket.on('new-message', (message) => {
      console.log('📨 NEW MESSAGE RECEIVED:', message);
      console.log('From:', message.from_user);
      console.log('Current user:', currentUsername);
      console.log('Chat open:', isChatOpen);

      // Add message to state
      setMessages(prev => [...prev, message]);

      // Only notify if message is from someone else
      if (message.from_user !== currentUsername) {
        console.log('🎯 Triggering notification!');

        // Play sound ALWAYS
        if (audioRef.current) {
          audioRef.current.play().catch(e => console.log('Audio play error:', e));
        }

        // Increment unread count
        setUnreadCount(prev => prev + 1);

        // ========== SHOW DESKTOP NOTIFICATION (WORKS EVEN WHEN CHAT CLOSED) ==========
        if (permissionGranted) {
          try {
            const notification = new Notification(`💬 New message from ${message.from_user}`, {
              body: message.message,
              icon: 'https://cdn-icons-png.flaticon.com/512/733/733585.png',
              tag: `msg-${message.id}-${Date.now()}`,
              requireInteraction: false,
              silent: false,
              vibrate: [200, 100, 200]
            });

            // When notification is clicked, focus window and optionally open chat
            notification.onclick = () => {
              console.log('Notification clicked - focusing window');
              window.focus();
              setIsChatOpen(true);
              notification.close();
            };

            // Auto-close notification after 5 seconds
            setTimeout(() => {
              try { notification.close(); } catch(e) {}
            }, 5000);

            console.log('✅ Desktop notification sent');
          } catch (notifError) {
            console.error('Notification error:', notifError);
          }
        } else {
          console.log('❌ Notification permission not granted. Current status:', Notification.permission);
        }

        // Also show browser alert if no permission (fallback)
        if (!permissionGranted && document.hidden) {
          console.log('Using fallback alert');
          // Optional: You could use a custom toast notification here
        }
      }
    });

    newSocket.on('online-users', (usersList) => {
      console.log('Online users:', usersList);
      setOnlineUsers(usersList);
    });

    newSocket.on('user-typing', (data) => {
      if (data.isTyping && data.from !== currentUsername) {
        setUserTyping(data.from);
        setTimeout(() => setUserTyping(null), 1500);
      }
    });

    setSocket(newSocket);

    return () => {
      console.log('Disconnecting chat...');
      if (newSocket) newSocket.disconnect();
    };
  }, [currentUsername, currentUser?.email, permissionGranted, isChatOpen]);

  // Reset unread count when chat is opened
  useEffect(() => {
    if (isChatOpen) {
      setUnreadCount(0);
    }
  }, [isChatOpen]);

  // Scroll to bottom when messages update
  useEffect(() => {
    if (isChatOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isChatOpen]);

  const sendMessage = () => {
    if (!inputMessage.trim() || !socket) return;

    console.log('Sending message:', inputMessage);

    socket.emit('send-message', {
      message: inputMessage,
      to: 'everyone'
    });

    setInputMessage('');
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    socket.emit('typing', { isTyping: false });
  };

  const handleTyping = () => {
    if (!socket) return;

    if (!typing) {
      setTyping(true);
      socket.emit('typing', { isTyping: true });
    }

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      setTyping(false);
      socket.emit('typing', { isTyping: false });
    }, 1000);
  };

  const toggleChat = () => {
    setIsChatOpen(!isChatOpen);
    if (!isChatOpen) {
      setUnreadCount(0);
    }
  };

  return (
    <>
      {/* Chat Bubble - Visible when chat is closed */}
      {!isChatOpen && (
        <div onClick={toggleChat} style={{
          position: 'fixed',
          bottom: '20px',
          right: '20px',
          width: '60px',
          height: '60px',
          borderRadius: '30px',
          background: 'linear-gradient(135deg, #7c3aed, #4f46e5)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          boxShadow: '0 4px 15px rgba(0,0,0,0.3)',
          zIndex: 1000,
          transition: 'transform 0.2s',
          animation: unreadCount > 0 ? 'pulse 2s infinite' : 'none'
        }}
        onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
        onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
        >
          <span style={{ fontSize: '28px' }}>💬</span>
          {unreadCount > 0 && (
            <div style={{
              position: 'absolute',
              top: '-5px',
              right: '-5px',
              background: '#ff3366',
              color: 'white',
              borderRadius: '50%',
              width: '24px',
              height: '24px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '12px',
              fontWeight: 'bold',
              animation: 'bounce 0.5s ease'
            }}>
              {unreadCount > 9 ? '9+' : unreadCount}
            </div>
          )}
          {connectionStatus === 'connected' && (
            <div style={{
              position: 'absolute',
              bottom: '2px',
              right: '2px',
              width: '12px',
              height: '12px',
              borderRadius: '50%',
              background: '#00ff96',
              border: '2px solid #1a1a2e',
              boxShadow: '0 0 5px #00ff96'
            }} />
          )}
        </div>
      )}

      {/* Chat Window - Only shown when open */}
      {isChatOpen && (
        <div style={{
          position: 'fixed',
          bottom: '20px',
          right: '20px',
          width: '420px',
          height: '550px',
          background: 'rgba(0, 8, 25, 0.98)',
          border: '1px solid rgba(0, 100, 255, 0.3)',
          borderRadius: '16px',
          backdropFilter: 'blur(20px)',
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
          zIndex: 1000,
          boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
          animation: 'slideUp 0.3s ease'
        }}>
          {/* Header */}
          <div style={{
            padding: '15px 20px',
            background: 'linear-gradient(135deg, #7c3aed, #4f46e5)',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <div>
              <span style={{ fontFamily: "'Orbitron', monospace", fontSize: '14px', fontWeight: 'bold' }}>
                💬 Team Chat
              </span>
              <div style={{ fontSize: '10px', opacity: 0.8 }}>
                {connectionStatus === 'connected' ? '🟢 Connected' : '🔴 Connecting...'}
              </div>
            </div>
            <div>
              <button onClick={toggleChat} style={{
                background: 'none',
                border: 'none',
                color: '#fff',
                fontSize: '16px',
                cursor: 'pointer',
                padding: '4px 8px'
              }} title="Minimize to bubble">
                ▼
              </button>
            </div>
          </div>

          {/* Notification Banner - Shows notifications were sent */}
          {unreadCount > 0 && !isChatOpen && (
            <div style={{
              padding: '8px 12px',
              background: 'rgba(255,51,102,0.2)',
              borderBottom: '1px solid rgba(0,100,255,0.2)',
              fontSize: '11px',
              textAlign: 'center'
            }}>
              📨 You have {unreadCount} new message{unreadCount !== 1 ? 's' : ''}!
            </div>
          )}

          {/* Online Users Bar */}
          <div style={{
            padding: '8px 12px',
            background: 'rgba(0, 20, 60, 0.6)',
            borderBottom: '1px solid rgba(0,100,255,0.2)',
            fontSize: '11px',
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            flexWrap: 'wrap'
          }}>
            <span style={{ color: '#7dd3fc' }}>👥 Online ({onlineUsers.length}):</span>
            {onlineUsers.length > 0 ? (
              onlineUsers.map(user => (
                <span key={user} style={{ 
                  background: 'rgba(0,255,150,0.15)', 
                  padding: '2px 8px',
                  borderRadius: '12px',
                  fontSize: '10px'
                }}>
                  {user}
                </span>
              ))
            ) : (
              <span style={{ opacity: 0.5 }}>No one else online</span>
            )}
          </div>

          {/* Messages Area */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '15px', display: 'flex', flexDirection: 'column' }}>
            {messages.slice(-50).map(msg => (
              <div
                key={msg.id}
                style={{
                  marginBottom: '12px',
                  display: 'flex',
                  justifyContent: msg.from_user === currentUsername ? 'flex-end' : 'flex-start'
                }}
              >
                <div style={{
                  maxWidth: '75%',
                  padding: '8px 14px',
                  borderRadius: '16px',
                  background: msg.from_user === currentUsername 
                    ? 'linear-gradient(135deg, #7c3aed, #4f46e5)'
                    : 'rgba(255,255,255,0.1)',
                  fontSize: '13px',
                  wordBreak: 'break-word'
                }}>
                  {msg.from_user !== currentUsername && (
                    <div style={{ fontSize: '10px', color: '#8b5cf6', marginBottom: '4px' }}>
                      {msg.from_user}
                    </div>
                  )}
                  {msg.message}
                  <div style={{ fontSize: '9px', opacity: 0.4, marginTop: '5px' }}>
                    {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                </div>
              </div>
            ))}
            {userTyping && userTyping !== currentUsername && (
              <div style={{ fontSize: '11px', color: '#7dd3fc', opacity: 0.7, marginBottom: '8px' }}>
                {userTyping} is typing...
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div style={{ padding: '12px', borderTop: '1px solid rgba(0,100,255,0.2)', display: 'flex', gap: '8px', background: 'rgba(0,0,0,0.3)' }}>
            <input
              type="text"
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              onKeyUp={handleTyping}
              placeholder="Type a message..."
              style={{
                flex: 1,
                padding: '10px 14px',
                background: 'rgba(0,20,60,0.8)',
                border: '1px solid rgba(0,100,255,0.3)',
                borderRadius: '20px',
                color: '#fff',
                outline: 'none',
                fontSize: '13px'
              }}
            />
            <button onClick={sendMessage} style={{
              padding: '8px 20px',
              background: 'linear-gradient(135deg, #7c3aed, #4f46e5)',
              border: 'none',
              borderRadius: '20px',
              color: '#fff',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: 'bold'
            }}>
              Send
            </button>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes bounce {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(1.2); }
        }
        @keyframes pulse {
          0%, 100% { box-shadow: 0 0 0 0 rgba(124, 58, 237, 0.7); }
          50% { box-shadow: 0 0 0 10px rgba(124, 58, 237, 0); }
        }
      `}</style>
    </>
  );
};

export default Chat;
